// ATTACK LAB runner. Run: bun run check:attacks
// Runs every attack in scripts/attacks/catalogue.ts against throwaway clones, judges each against its expected outcome (kind, reason code, money unchanged,
// log presence, nothing signed or executed), and runs the money attacks again with the permission gate REMOVED (a test double in scripts/ only).
// Exits non-zero if any attack succeeds. Output is deterministic: no timestamps, ids replaced by stable labels, sorted. Writes fixtures/attack-results.json
// and docs/attack-results.md (both generated by this command).
import assert from "node:assert/strict";
import { mkdirSync, writeFileSync } from "node:fs";
import { Harness } from "./attacks/harness";
import { CATALOGUE } from "./attacks/catalogue";
import { BASELINE_LABEL } from "./attacks/no-gate";
import type { Attack, Result } from "./attacks/types";

const ORDER = ["Money through the gate", "Untrusted text", "Plan integrity", "Privilege", "Evidence", "AI output", "Secrets"];
const GBP2 = (minor: bigint) => `${(minor / 100n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${(minor % 100n).toString().padStart(2, "0")}`;

function judge(a: Attack, o: Result["observed"]): string[] {
  const problems: string[] = [];
  if (o.kind !== a.expected.kind) problems.push(`expected ${a.expected.kind}, the system did: ${o.kind}`);
  const wanted = Array.isArray(a.expected.code) ? a.expected.code : [a.expected.code];
  if (!o.code.split("+").some((c) => wanted.includes(c))) problems.push(`expected reason code ${wanted.join(" or ")}, got ${o.code}`);
  if (!o.moneyUnchanged) problems.push("money-bearing state changed");
  if (!o.nothingSignedOrExecuted) problems.push("something was signed or executed as a side effect");
  if (a.expected.logged && o.events.length === 0) problems.push("the attempt should be in the audit log but nothing was logged");
  if (!a.expected.logged && o.events.length > 0) problems.push(`the attempt should be refused before logging, but it logged ${o.events.join(", ")}`);
  return problems;
}

async function main() {
  const ids = CATALOGUE.map((a) => a.id);
  assert.equal(new Set(ids).size, ids.length, "attack ids are unique");
  const h = await Harness.create();
  const results: Result[] = [];
  try {
    for (const a of CATALOGUE) {
      let observed;
      try { observed = await a.run(h); } catch (e) { observed = { kind: "error", code: "harness", reason: e instanceof Error ? e.message : String(e), events: [], moneyUnchanged: false, nothingSignedOrExecuted: false }; }
      let baseline: Result["baseline"] = null;
      if (a.moneyAttack && a.baseline) {
        try { const b = await a.baseline(h); baseline = { outcome: b.outcome, movedMinor: b.movedMinor.toString(), note: h.stable(b.note) }; }
        catch (e) { baseline = { outcome: "none", movedMinor: "0", note: `baseline could not run: ${e instanceof Error ? e.message : String(e)}` }; }
      } else if (a.baseline) {
        try { const b = await a.baseline(h); baseline = { outcome: b.outcome, movedMinor: b.movedMinor.toString(), note: h.stable(b.note) }; } catch { baseline = { outcome: "n/a", movedMinor: "0", note: "not a money movement" }; }
      }
      const problems = judge(a, observed);
      results.push({ id: a.id, category: a.category, title: a.title, threat: a.threat, expected: a.expected, observed, passed: problems.length === 0, problems, baseline });
      console.log(`  ${problems.length === 0 ? "BLOCKED" : "FAILED "} ${a.id} ${a.title.slice(0, 92)} -> ${observed.kind} ${observed.code}${baseline ? ` | without the gate: ${baseline.outcome}${baseline.outcome === "moved" ? ` GBP ${GBP2(BigInt(baseline.movedMinor))}` : ""}` : ""}${problems.length ? `  PROBLEMS: ${problems.join("; ")}` : ""}`);
    }
  } finally {
    await h.close();
  }

  results.sort((x, y) => ORDER.indexOf(x.category) - ORDER.indexOf(y.category) || (x.id < y.id ? -1 : 1));
  const money = results.filter((r) => r.baseline && r.baseline.outcome !== "n/a" && CATALOGUE.find((a) => a.id === r.id)!.moneyAttack);
  const moved = money.filter((r) => r.baseline!.outcome === "moved");
  const total = results.length;
  const blocked = results.filter((r) => r.passed).length;
  const summary = { attacks: total, blocked, moneyAttacks: money.length, movedWithoutGate: moved.length, movedWithoutGateMinor: moved.reduce((n, r) => n + BigInt(r.baseline!.movedMinor), 0n).toString() };

  mkdirSync("fixtures", { recursive: true });
  writeFileSync("fixtures/attack-results.json", JSON.stringify({ generatedBy: "bun run check:attacks", asOf: "2026-10-15", baselineLabel: BASELINE_LABEL, summary, results }, null, 2) + "\n");
  const md: string[] = [
    "<!-- generated by bun run check:attacks -->",
    "# Attack lab results",
    "",
    "_Generated by `bun run check:attacks`. Do not edit by hand._",
    "",
    "Threat model: the planner, a document or a counterparty is assumed to be compromised. Nothing here says anything about how a particular language model behaves.",
    "",
    `**${summary.attacks} attacks tried, ${summary.blocked} blocked.** Without the permission gate, ${summary.movedWithoutGate} of the ${summary.moneyAttacks} money attacks would have moved money (GBP ${GBP2(BigInt(summary.movedWithoutGateMinor))} in total across the separate runs).`,
    "",
    `> ${BASELINE_LABEL}`,
    "",
  ];
  for (const cat of ORDER) {
    const rs = results.filter((r) => r.category === cat);
    if (rs.length === 0) continue;
    md.push(`## ${cat}`, "", "| Id | What the attacker tried | With protections | Logged? | Without the gate |", "|---|---|---|---|---|");
    for (const r of rs) {
      const withP = r.passed ? `Blocked: ${r.observed.kind} (${r.observed.code})` : `NOT BLOCKED: ${r.problems.join("; ")}`;
      const lg = r.observed.events.length > 0 ? `yes (${r.observed.events.join(", ")})` : "no: refused before logging";
      const wo = !r.baseline ? "not applicable" : r.baseline.outcome === "moved" ? `money moved: GBP ${GBP2(BigInt(r.baseline.movedMinor))}` : r.baseline.outcome === "none" ? `no money moved (${r.baseline.note})` : "not applicable";
      md.push(`| ${r.id} | ${r.title.replaceAll("|", "/")} | ${withP.replaceAll("|", "/")} | ${lg.replaceAll("|", "/")} | ${wo.replaceAll("|", "/")} |`);
    }
    md.push("");
  }
  writeFileSync("docs/attack-results.md", md.join("\n") + "\n");

  console.log(`\nattack lab: ${blocked} of ${total} attacks blocked; without the permission gate ${moved.length} of ${money.length} money attacks moved money (GBP ${GBP2(BigInt(summary.movedWithoutGateMinor))} across separate runs)`);
  if (blocked !== total) { console.error("SOME ATTACKS SUCCEEDED"); process.exit(1); }
}

main().catch((e) => { console.error(e); process.exit(1); });
